mapper.select:
SELECT p.id, p.package_id AS packageId, p.package_code AS packageCode, p.warehouse_id AS warehouseId, w.node_name AS warehouseName, p.package_status AS packageStatus, p.create_user AS createUser, e.actual_name AS createUserName, p.create_time AS createTime, p.remark FROM spd_package_main p LEFT JOIN spd_org_node w ON p.warehouse_id = w.node_id AND w.del_flag = 0 LEFT JOIN t_employee e ON p.create_user = e.employee_id AND e.deleted = 0 WHERE p.del_flag = #{delFlag}
AND p.package_code LIKE CONCAT('%', #{query.packageCode}, '%')
AND p.warehouse_id = #{query.warehouseId}
AND p.package_status = #{query.packageStatus}
ORDER BY p.create_time DESC
